-- PT113-S4-Q1. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT113-S4-Q1$batch08$ AND q.stimulus=$batch08$Criminals often have an unusual self-image. Embezzlers often think of their actions as “only borrowing money.” Many people convicted of violent crimes rationalize their actions by some sort of denial; either the victim “deserved it” and so the action was justified, or “it simply wasn’t my fault. ” Thus, in many cases, by criminals’ characterization of their situations, _______.$batch08$ AND q.prompt=$batch08$Which one of the following most logically completes the passage?$batch08$ AND q.correct_choice=$batch08$C$batch08$) THEN RAISE EXCEPTION 'Question changed: PT113-S4-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT113-S4-Q1$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S4-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT113-S4-Q1$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Embezzlers call it "only borrowing". Violent criminals say the victim "deserved it", so it was justified, or that it "simply wasn't my fault".$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer. Every example is a criminal describing the act so that it stops being a crime: borrowing isn't theft, a justified act isn't wrongdoing, and if it wasn't your fault, you didn't do anything criminal. The blank asks what follows "by criminals' characterization".$batch08$), (2, $batch08$Goal$batch08$, $batch08$In their own telling, what they did wasn't really a crime.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT113-S4-Q1$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Saying an act wasn't wrong is not saying it deserves a reward. None of the examples claim credit.$batch08$), ($batch08$B$batch08$, $batch08$This is the most popular wrong answer. "The victim deserved it" puts blame on the victim; it doesn't make the criminal a victim of some other criminal. No example says that.$batch08$), ($batch08$C$batch08$, $batch08$Borrowing, justified, not my fault: each description denies that the act was criminal. That is what all three examples share.$batch08$), ($batch08$D$batch08$, $batch08$The criminals talk about their own acts, not the justice system.$batch08$), ($batch08$E$batch08$, $batch08$These criminals aren't asking for leniency. They deny there was a crime at all.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT113-S4-Q1$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
